'use client';
import {
  STAGE_LABELS,
  type CareerStage,
  type JobTemplate,
  type ContentSource,
} from '@interviewlab/core';
import { ArrowRight, Copy, ExternalLink, Search } from 'lucide-react';
import Link from 'next/link';
import { useSearchParams } from 'next/navigation';
import { useCallback, useEffect, useState } from 'react';
import {BookmarkButton} from './bookmark-button';
import { jobsApi } from '../lib/api/jobs';
import { ErrorNotice, useLiveResource } from '../features/live-interview/common';
import { EmptyState, Footer, Header, Loading } from './shared';
import { Button } from './ui/button';

export function JobLibrary() {
  const params = useSearchParams();
  const [cursor, setCursor] = useState('');
  const [query, setQuery] = useState(''),
    [category, setCategory] = useState(params.get('category') ?? ''),
    [stage, setStage] = useState<CareerStage | ''>('');
  useEffect(() => {
    setCategory(params.get('category') ?? '');
    setCursor('');
  }, [params]);
  const load = useCallback(
    (signal: AbortSignal) => {
      const querystring = new URLSearchParams({ limit: '20' });
      if (query) querystring.set('search', query);
      if (category) querystring.set('category', category);
      if (stage) querystring.set('stage', stage);
      if (cursor) querystring.set('cursor', cursor);
      return jobsApi.list(querystring.toString(), signal);
    },
    [query, category, stage, cursor],
  );
  const resource = useLiveResource(load, () => false);
  const categoriesLoad = useCallback((signal: AbortSignal) => jobsApi.categories(signal), []);
  const categories = useLiveResource(categoriesLoad, () => false);
  const jobs = resource.value?.items ?? [];
  return (
    <>
      <Header />
      <main id="main-content" className="jobs-page">
        <section className="jobs-banner">
          <div className="container jobs-banner-inner">
            <div>
              <h1>岗位库</h1>
              <p>选一个方向，把准备做得更具体。</p>
            </div>
            <div className="jobs-search-controls">
              <label className="search-box">
                <Search size={21} />
                <input
                  aria-label="搜索岗位或技能"
                  placeholder="搜索岗位或技能，如 Agent、产品、SQL"
                  value={query}
                  onChange={(e) => {
                    setQuery(e.target.value);
                    setCursor('');
                  }}
                />
              </label>
              <div className="row-actions">
                <span>适用阶段</span>
                <div className="segmented" role="group" aria-label="筛选适用阶段">
                  {(['', 'internship', 'campus'] as const).map((s) => (
                    <button
                      key={s}
                      aria-pressed={stage === s}
                      onClick={() => {
                        setStage(s);
                        setCursor('');
                      }}
                    >
                      {s ? STAGE_LABELS[s] : '全部'}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </section>
        <div className="container jobs-layout">
          <aside className="job-categories">
            <h2>方向分类</h2>
            <nav aria-label="岗位方向">
              <button
                aria-pressed={!category}
                onClick={() => {
                  setCategory('');
                  setCursor('');
                }}
              >
                全部方向
              </button>
              {categories.value?.items.map((c) => (
                <button
                  key={c.id}
                  aria-pressed={category === c.id}
                  onClick={() => {
                    setCategory(c.id);
                    setCursor('');
                  }}
                >
                  {c.title}
                </button>
              ))}
            </nav>
          </aside>
          <div className="job-results">
            <div className="section-title-row">
              <p>岗位模板</p>
              <Link className="text-link" href="/me/saved-jobs">
                我的目标岗位
                <ArrowRight size={16} />
              </Link>
            </div>
            <ErrorNotice message={resource.error} retry={() => void resource.refresh()} />
            <ErrorNotice message={categories.error} retry={() => void categories.refresh()} />
            {!resource.value && !resource.error && <Loading />}
            <p className="muted">点击岗位旁的收藏按钮，可在个人中心的目标岗位中集中查看。</p>
            <div className="catalog-rows">
              {jobs.map((j) => (
                <article className="catalog-job" key={j.id}>
                  <div>
                    <h2>
                      <Link href={`/jobs/${j.slug}`}>{j.title}</Link>
                    </h2>
                    <p>{j.description}</p>
                    <div className="catalog-tags">
                      {j.tags.map((t) => (
                        <span key={t}>{t}</span>
                      ))}
                    </div>
                  </div>
                  <div className="catalog-actions">
                    <BookmarkButton id={j.id} />
                    <Link className="text-link" href={`/jobs/${j.slug}`}>
                      查看岗位
                      <ArrowRight size={18} />
                    </Link>
                  </div>
                </article>
              ))}
            </div>
            {resource.value && !jobs.length && (
              <EmptyState
                title="没有找到对应岗位"
                description="试试其他岗位名称、技能关键词，或切换方向分类。"
              />
            )}
            <div className="row-actions">
              {cursor && (
                <Button variant="outline" onClick={() => setCursor('')}>
                  回到第一页
                </Button>
              )}
              {resource.value?.next_cursor && (
                <Button variant="outline" onClick={() => setCursor(resource.value!.next_cursor!)}>
                  下一页
                </Button>
              )}
            </div>
            <p className="catalog-note">
              通用参考模板，面向实习与校招整理。企业实际要求请核对原招聘信息。
            </p>
          </div>
        </div>
      </main>
      <Footer />
    </>
  );
}

export function LiveJobDetail({ id }: { id: string }) {
  const load = useCallback((signal: AbortSignal) => jobsApi.read(id, signal), [id]);
  const resource = useLiveResource(load, () => false);
  if (!resource.value)
    return (
      <>
        <Header />
        <main id="main-content" className="container section">
          <ErrorNotice message={resource.error} retry={() => void resource.refresh()} />
          {!resource.error && <Loading />}
        </main>
        <Footer />
      </>
    );
  return <JobDetail job={resource.value} sources={resource.value.sources} />;
}
export function JobDetail({ job, sources }: { job: JobTemplate; sources: ContentSource[] }) {
  return (
    <>
      <Header />
      <main id="main-content" className="job-detail-page">
        <section className="jobs-banner">
          <div className="container">
            <div className="job-breadcrumb">
              <Link href="/jobs">岗位库</Link>
              <span>/</span>
              <Link href={`/jobs?category=${job.category_id}`}>{job.category_id}</Link>
              <span>/</span>
              <span>{job.title}</span>
            </div>
            <div className="job-detail-heading">
              <div>
                <h1>{job.title}</h1>
                <p>{job.description}</p>
              </div>
              <div className="row-actions wrap">
                <Button asChild>
                  <Link href={`/interview/setup?job=${job.id}`}>
                    使用模板模拟
                    <ArrowRight size={18} />
                  </Link>
                </Button>
                <BookmarkButton id={job.id} />
              </div>
            </div>
          </div>
        </section>
        <div className="container job-detail-layout">
          <div>
            <nav className="job-detail-nav" aria-label="岗位详情章节">
              <a href="#job-jd">岗位 JD</a>
              <a href="#job-topics">考查主题</a>
              <a href="#job-questions">典型问题</a>
              <a href="#job-sources">资料来源</a>
            </nav>
            <article className="job-article library-panel" id="job-jd">
              {(
                [
                  ['responsibilities', '岗位职责'],
                  ['requirements', '基础要求'],
                  ['preferred', '加分项'],
                ] as const
              ).map(([key, title]) => (
                <section key={key}>
                  <h2>{title}</h2>
                  <ol>
                    {job[key].map((text) => (
                      <li key={text}>{text}</li>
                    ))}
                  </ol>
                </section>
              ))}
              <p className="muted">{job.jd_note}</p>
            </article>
            <section id="job-topics" className="library-panel">
              <h2>考查主题</h2>
              <div className="topic-grid">
                {job.topics.map((t, i) => (
                  <div key={t}>
                    <span>{String(i + 1).padStart(2, '0')}</span>
                    <strong>{t}</strong>
                  </div>
                ))}
              </div>
            </section>
            <section id="job-questions" className="library-panel">
              <div className="section-title-row">
                <h2>典型问题</h2>
                <span className="badge badge-mint">平台整理 · 8 题</span>
              </div>
              <p className="muted">
                用于了解准备方向，面试中不展示参考要点。未经过企业真题认证或专业评分校准。
              </p>
              <div className="knowledge-questions">
                {job.questions.map((q, i) => (
                  <details key={q.id}>
                    <summary>
                      <span className="question-number">{i + 1}</span>
                      <strong>{q.text}</strong>
                    </summary>
                    <div className="question-preparation">
                      <p>{q.intent}</p>
                      <h3>观察要点</h3>
                      <p>{q.observation_points.join('、')}</p>
                      <h3>追问方向</h3>
                      <ul>
                        {q.follow_ups.map((f) => (
                          <li key={f}>{f}</li>
                        ))}
                      </ul>
                      <p className="muted">
                        适用：{q.stages.map((s) => STAGE_LABELS[s]).join(' / ')} · {q.difficulty}
                      </p>
                      {q.source_refs.map((id) => {
                        const s = sources.find((s) => s.id === id);
                        return s ? (
                          <a
                            key={id}
                            href={s.url}
                            target="_blank"
                            rel="noreferrer"
                            className="text-link"
                          >
                            知识参考
                            <ExternalLink size={14} />
                          </a>
                        ) : null;
                      })}
                    </div>
                  </details>
                ))}
              </div>
            </section>
            <section id="job-sources" className="library-panel source-list">
              <h2>资料来源与版本</h2>
              <p>
                模板 v{job.version} · 核对于 {job.reviewed_at} · 下次复核 {job.review_due_at}
              </p>
              {sources.map((s) => (
                <div key={s.id}>
                  <a href={s.url} target="_blank" rel="noreferrer" className="text-link">
                    {s.title}
                    <ExternalLink size={16} />
                  </a>
                  <p>
                    {s.kind === 'recruitment' ? '岗位需求参考' : '官方知识参考'} ·{' '}
                    {s.verification === 'page_read' ? '已查阅公开页面' : '仅检索摘要可访问'} ·{' '}
                    {s.reviewed_at}
                  </p>
                  <p className="muted">{s.notes}</p>
                </div>
              ))}
            </section>
          </div>
          <aside className="job-preparation">
            <h2>准备这类面试</h2>
            <p>
              {STAGE_LABELS.internship} / {STAGE_LABELS.campus}
            </p>
            <ol>
              {job.topics.slice(0, 4).map((t) => (
                <li key={t}>{t}</li>
              ))}
            </ol>
            <Button variant="outline" disabled>
              <Copy size={17} />
              个人 JD 暂未开放
            </Button>
          </aside>
        </div>
      </main>
      <Footer />
    </>
  );
}

'use client';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import {
  ArrowRight,
  BarChart3,
  ChevronRight,
  Code2,
  Database,
  FlaskConical,
  Menu,
  UserRound,
  X,
} from 'lucide-react';
import * as Dialog from '@radix-ui/react-dialog';
import { useRef, useState } from 'react';
import { Button } from './ui/button';
import { AccountControls } from './account-controls';
export function Brand() {
  return (
    <Link href="/" className="brand" aria-label="InterviewLab 首页">
      <span className="brand-mark" aria-hidden="true">
        <i />
        <i />
        <i />
      </span>
      <span>
        InterviewLab<small>面试练习室</small>
      </span>
    </Link>
  );
}
export function Header() {
  const path = usePathname();
  const [open, setOpen] = useState(false);
  return (
    <header className="site-header">
      <div className="container header-inner">
        <Brand />
        <nav aria-label="主导航" className={open ? 'main-nav is-open' : 'main-nav'}>
          <Link onClick={() => setOpen(false)} className={path === '/' ? 'active' : ''} href="/">
            首页
          </Link>
          <Link
            onClick={() => setOpen(false)}
            className={path.startsWith('/interview') ? 'active' : ''}
            href="/interview/setup"
          >
            模拟面试
          </Link>
          <Link
            onClick={() => setOpen(false)}
            className={path.startsWith('/jobs') ? 'active' : ''}
            href="/jobs"
          >
            岗位库
          </Link>
          <Link onClick={() => setOpen(false)} href="/#faq">
            常见问题
          </Link>
        </nav>
        <div className="header-actions">
          <span className="badge badge-yellow">文字面试 Beta</span>
          <AccountControls />
          <Link href="/me" className="user-link">
            <UserRound size={17} />
            <span>个人中心</span>
            <ChevronRight size={14} />
          </Link>
          <button
            className="menu-toggle"
            aria-label={open ? '关闭导航' : '展开导航'}
            aria-expanded={open}
            onClick={() => setOpen(!open)}
          >
            {open ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>
      </div>
    </header>
  );
}
export function Footer() {
  return (
    <footer className="site-footer">
      <div className="container footer-inner">
        <Brand />
        <p>每一次练习，都从自己的经历出发。</p>
        <span>真实文字面试 · 记录归属当前账号</span>
      </div>
    </footer>
  );
}
export function Breadcrumb({ items }: { items: string[] }) {
  return (
    <div className="breadcrumb">
      <Link href="/">首页</Link>
      {items.map((item, i) => (
        <span key={i}>
          <ChevronRight size={13} />
          {item}
        </span>
      ))}
    </div>
  );
}
export function JobIcon({ job, size = 24 }: { job: string; size?: number }) {
  const Icon =
    job === 'frontend'
      ? Code2
      : ['backend', 'python', 'golang', 'database', 'data-warehouse', 'data-engineering'].includes(
            job,
          )
        ? Database
        : [
              'algorithm',
              'llm-app',
              'llm-training',
              'nlp',
              'cv',
              'speech',
              'recommendation',
              'ai-infra',
              'ai-product',
              'data-analysis',
            ].includes(job)
          ? BarChart3
          : FlaskConical;
  return <Icon size={size} />;
}
export function EmptyState({
  title,
  description,
  href,
  action,
}: {
  title: string;
  description: string;
  href?: string;
  action?: string;
}) {
  return (
    <div className="empty-state">
      <div className="empty-icon">
        <BarChart3 size={28} />
      </div>
      <h2>{title}</h2>
      <p>{description}</p>
      {href && (
        <Button asChild>
          <Link href={href}>
            {action ?? '开始一次练习'}
            <ArrowRight size={16} />
          </Link>
        </Button>
      )}
    </div>
  );
}
export function Modal({
  open,
  onOpenChange,
  title,
  description,
  children,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description?: string;
  children: React.ReactNode;
}) {
  const previousFocus = useRef<HTMLElement | null>(null);
  return (
    <Dialog.Root open={open} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Overlay className="dialog-overlay" />
        <Dialog.Content
          className="dialog-content"
          onOpenAutoFocus={() => {
            previousFocus.current =
              document.activeElement instanceof HTMLElement ? document.activeElement : null;
          }}
          onCloseAutoFocus={(event) => {
            event.preventDefault();
            const original = previousFocus.current;
            const destination =
              original?.isConnected && original.tagName !== 'BODY'
                ? original
                : document.querySelector<HTMLElement>('main button, main a[href]');
            destination?.focus();
          }}
        >
          <div className="dialog-heading">
            <Dialog.Title>{title}</Dialog.Title>
            <Dialog.Close className="icon-button" aria-label="关闭弹窗">
              <X size={20} />
            </Dialog.Close>
          </div>
          <Dialog.Description className={description ? 'dialog-description' : 'sr-only'}>
            {description ?? title}
          </Dialog.Description>
          {children}
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}
export function Loading() {
  return (
    <div className="loading" role="status">
      <span className="spinner" />
      正在准备页面…
    </div>
  );
}
export function formatDate(iso: string) {
  return new Intl.DateTimeFormat('zh-CN', {
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'Asia/Shanghai',
  }).format(new Date(iso));
}
export function formatTime(seconds: number) {
  return `${Math.floor(seconds / 60)
    .toString()
    .padStart(2, '0')}:${(seconds % 60).toString().padStart(2, '0')}`;
}

'use client';

import Link from 'next/link';
import { useCallback, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { liveInterviewPath, type Interview, type InterviewReport } from '@interviewlab/core';
import { interviewSetupPath } from './setup-state';
import { Button } from '../../components/ui/button';
import { ApiClientError } from '../../lib/api/http';
import { interviewsApi } from '../../lib/api/interviews';
import { SessionGate, useLiveCommand, useLiveResource } from './common';
import { reportDisplayState, reportRetryScope, type ReportDisplayState } from './report-progress';
import { analysisPresentation } from './analysis-state';
import { TransitionScreen } from './transition-screen';

interface AnalysisWaitingProps {
  id: string;
  interview: Interview | null;
  report: InterviewReport | null;
  error?: string;
  refreshing?: boolean;
  refresh: () => void;
  onReport: (report: InterviewReport) => void;
}

interface AnalysisActionProps extends Omit<AnalysisWaitingProps, 'onReport'> {
  state: ReportDisplayState;
  command: ReturnType<typeof useLiveCommand>;
  retry: () => void;
}

function AnalysisRetryAction({
  interview,
  error,
  refreshing,
  refresh,
  state,
  command,
  retry,
}: AnalysisActionProps) {
  if (command.unresolved)
    return (
      <Button onClick={command.retry} disabled={command.busy}>
        确认并重试原操作
      </Button>
    );
  if (error)
    return (
      <Button onClick={refresh} disabled={refreshing}>
        重新连接
      </Button>
    );
  if (!interview || !['failed', 'unrequested'].includes(state)) return null;
  const label = command.busy
    ? '正在恢复分析…'
    : state === 'unrequested'
      ? '生成完整复盘'
      : '重试未完成的分析';
  return (
    <Button onClick={retry} disabled={command.blocked}>
      {label}
    </Button>
  );
}

function AnalysisActions(props: AnalysisActionProps) {
  const { id, interview, report, state } = props;
  const empty = state === 'empty';
  const partial = ['failed', 'empty', 'unrequested'].includes(state) && interview && report;
  return (
    <div className="transition-actions">
      <AnalysisRetryAction {...props} />
      {partial && (
        <Button variant="outline" asChild>
          <Link href={`/reports/${id}?view=partial`}>
            {empty ? '查看本场记录' : '查看已完成结果'}
          </Link>
        </Button>
      )}
      {empty && (
        <Button asChild>
          <Link
            href={interviewSetupPath(interview?.configuration.job)}
          >
            重新开始练习
          </Link>
        </Button>
      )}
      <Button variant="ghost" asChild>
        <Link href="/me/interviews">稍后查看</Link>
      </Button>
    </div>
  );
}

export function AnalysisWaiting({
  id,
  interview,
  report,
  error = '',
  refreshing = false,
  refresh,
  onReport,
}: AnalysisWaitingProps) {
  const command = useLiveCommand(refresh);
  const { state, ...presentation } = analysisPresentation(interview, report);
  const retry = () =>
    command.run(
      (key) => interviewsApi.retryReport(id, report?.version ?? 1, key, reportRetryScope(report)),
      onReport,
    );
  return (
    <TransitionScreen
      kind="analysis"
      {...presentation}
      error={
        command.error ||
        error ||
        (state === 'failed' ? '成功结果和原回答均已保存。重试只处理未完成的部分。' : undefined)
      }
    >
      <AnalysisActions
        id={id}
        interview={interview}
        report={report}
        error={error}
        refreshing={refreshing}
        refresh={refresh}
        state={state}
        command={command}
        retry={retry}
      />
    </TransitionScreen>
  );
}

function AnalysisBody({ id }: { id: string }) {
  const router = useRouter();
  const load = useCallback(
    async (signal: AbortSignal) => {
      const interview = await interviewsApi.read(id, signal);
      let report: InterviewReport | null = null;
      if (['completed', 'failed'].includes(interview.status)) {
        try {
          report = await interviewsApi.report(id, signal);
        } catch (error) {
          if (!(error instanceof ApiClientError && error.status === 404)) throw error;
        }
      }
      return { interview, report };
    },
    [id],
  );
  const resource = useLiveResource(
    load,
    (value) => reportDisplayState(value.report) === 'pending',
    { retryReadErrors: true },
  );
  const data = resource.value;
  useEffect(() => {
    if (!data) return;
    if (!['completed', 'failed'].includes(data.interview.status))
      router.replace(liveInterviewPath(data.interview));
    else if (['ready', 'empty'].includes(reportDisplayState(data.report)))
      router.replace(`/reports/${id}`);
  }, [data, id, router]);
  return (
    <AnalysisWaiting
      id={id}
      interview={data?.interview ?? null}
      report={data?.report ?? null}
      error={resource.error}
      refreshing={resource.refreshing}
      refresh={() => void resource.refresh()}
      onReport={(report) => {
        if (data) resource.accept({ ...data, report });
      }}
    />
  );
}

export default function LiveAnalysis({ id }: { id: string }) {
  return (
    <SessionGate>
      <AnalysisBody id={id} />
    </SessionGate>
  );
}

'use client';
import Link from 'next/link';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useSession } from '../../components/session-provider';
import { Header, Loading } from '../../components/shared';
import { ApiClientError } from '../../lib/api/http';
import { Button } from '../../components/ui/button';

export function LiveFrame({ children, title }: { children: React.ReactNode; title: string }) {
  return (
    <>
      <Header />
      <main id="main-content" className="container page-body live-page">
        <div className="live-heading">
